  static std::unique_ptr<Instruction> subDecodeVop3p(const MachineInst *opcode);
  static std::unique_ptr<Instruction> subDecodeVinterp(const MachineInst *opcode);
  static std::unique_ptr<Instruction> subDecodeVdsdir(const MachineInst *opcode);
  static std::unique_ptr<Instruction> subDecodeVimage(const MachineInst *opcode);
  static std::unique_ptr<Instruction> subDecodeVop3(const MachineInst *opcode);
  static std::unique_ptr<Instruction> subDecodeVds(const MachineInst *opcode);
  static std::unique_ptr<Instruction> subDecodeVsample(const MachineInst *opcode);
  static std::unique_ptr<Instruction> subDecodeVflat(const MachineInst *opcode);
  static std::unique_ptr<Instruction> subDecodeVscratch(const MachineInst *opcode);
  static std::unique_ptr<Instruction> subDecodeVglobal(const MachineInst *opcode);
  static std::unique_ptr<Instruction> subDecodeSmem(const MachineInst *opcode);
  static const std::array<DecodeFunc, 512> primary_decode_table;
  static const std::array<DecodeFunc, 256> sub_decode_vopc;
